import{_ as l,a0 as p,w as d,s as o,ao as r,I as n,x as s,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何从 Linux 命令行安装软件 | LCTT x X-CMD","titleTemplate":false,"description":"如何从 Linux 命令行安装软件 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何从 Linux 命令行安装软件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何从 Linux 命令行安装软件 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180824 How to install software from the Linux command line","title":"如何从 Linux 命令行安装软件","tag":"201809","desc":""},"relativePath":"201809/20180824 How to install software from the Linux command line.md","filePath":"[post].md"}'),u={name:"201809/20180824 How to install software from the Linux command line.md"};function h(g,e,b,k,c,m){const i=p("Link");return d(),o("div",null,[e[22]||(e[22]=r(`<h1 id="如何从-linux-命令行安装软件" tabindex="-1">如何从 Linux 命令行安装软件 <a class="header-anchor" href="#如何从-linux-命令行安装软件" aria-label="Permalink to “如何从 Linux 命令行安装软件”">​</a></h1><blockquote><p>学习一种不同的包管理器和怎么使用它。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/suitcase_container_bag.png?itok=q40lKCBY" alt=""></p><p>如果你在一直在使用 Linux，你很快就会发现做同样的事情有很多不同的方法。这包括通过命令行在 Linux 上安装应用。我已经是大约 25 年的 Linux 用户，我一次又一次地回到命令行来安装我的应用。</p><p>从命令行安装应用程序最常用的方法是使用称为包管理器通过软件库（存储软件的地方）安装。所有 Linux 应用都作为软件包分发，这些软件包只不过是与软件包管理系统相关的文件。每个 Linux 发行版都附带一个包管理系统，但它们并不完全相同。</p><h3 id="什么是包管理系统" tabindex="-1">什么是包管理系统？ <a class="header-anchor" href="#什么是包管理系统" aria-label="Permalink to “什么是包管理系统？”">​</a></h3><p>包管理系统由一组工具和文件格式组成，它们一起用于安装、更新和卸载 Linux 应用。两种最常见的包管理系统来自 Red Hat 和 Debian。 Red Hat、CentOS 和 Fedora 都使用 <code>rpm</code> 系统（.rpm 文件），而 Debian、Ubuntu、Mint 和 Ubuntu 都使用 <code>dpkg</code>（.deb 文件）。Gentoo Linux 使用名为 Portage 的系统，Arch Linux 只使用 tarball（.tar 文件）。这些系统之间的主要区别在于它们如何安装和维护应用。</p><p>你可能想知道 <code>.rpm</code>、<code>.deb</code> 或 <code>.tar</code> 文件中的内容。你可能会惊讶地发现，所有这些都只是普通的老式归档文件（如 <code>.zip</code>），其中包含应用的代码，如何安装它的说明，依赖项（它可能依赖的其他应用），以及配置文件的位置。读取和执行所有这些指令的软件称为包管理器。</p><h3 id="debian、ubuntu、mint-等" tabindex="-1">Debian、Ubuntu、Mint 等 <a class="header-anchor" href="#debian、ubuntu、mint-等" aria-label="Permalink to “Debian、Ubuntu、Mint 等”">​</a></h3><p>Debian、Ubuntu、Mint 和其它基于 Debian 的发行版都使用 <code>.deb</code> 文件和 <code>dpkg</code> 包管理系统。有两种方法可以通过此系统安装应用。你可以使用 <code>apt</code> 程序从仓库进行安装，也可以使用 <code>dpkg</code> 程序从 <code>.deb</code> 文件安装应用。我们来看看如何做到这两点。</p><p>使用 <code>apt</code> 安装应用非常简单：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install app_name</span></span></code></pre></div><p>通过 <code>apt</code> 卸载应用也非常简单：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt remove app_name</span></span></code></pre></div><p>要升级已安装的应用，首先需要更新应用仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span></code></pre></div><p>完成后，你可以使用以下命令更新任何程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt upgrade</span></span></code></pre></div><p>如果你只想更新一个应用，该怎么办？没问题。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update app_name</span></span></code></pre></div><p>最后，假设你要安装的应用不存在于 Debian 仓库中，但有 <code>.deb</code> 下载。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dpkg -i app_name.deb</span></span></code></pre></div><h3 id="red-hat、centos-和-fedora" tabindex="-1">Red Hat、CentOS 和 Fedora <a class="header-anchor" href="#red-hat、centos-和-fedora" aria-label="Permalink to “Red Hat、CentOS 和 Fedora”">​</a></h3><p>默认情况下，Red Hat 使用多个包管理系统。这些系统在使用自己的命令时，互相仍然非常相似，而且与 Debian 中使用的也相似。例如，我们可以使用 <code>yum</code> 或 <code>dnf</code> 管理器来安装应用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install app_name</span></span>
<span class="line"><span>$ sudo dnf install app_name</span></span></code></pre></div><p><code>.rpm</code> 格式的应用也可以使用 <code>rpm</code> 命令安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rpm -i app_name.rpm</span></span></code></pre></div><p>删除不需要的应用同样容易。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum remove app_name</span></span>
<span class="line"><span>$ sudo dnf remove app_name</span></span></code></pre></div><p>更新应用同样容易。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yum update</span></span>
<span class="line"><span>$ sudo dnf upgrade --refresh</span></span></code></pre></div><p>如你所见，从命令行安装、卸载和更新 Linux 应用并不难。事实上，一旦你习惯它，你会发现它比使用基于桌面 GUI 的管理工具更快！</p>`,32)),n("p",null,[e[3]||(e[3]=s("有关从命令行安装应用程序的更多信息，请访问 Debian ",-1)),a(i,{href:"https://wiki.debian.org/Apt"},{default:t(()=>[...e[0]||(e[0]=[s("Apt wiki",-1)])]),_:1}),e[4]||(e[4]=s("、",-1)),a(i,{href:"https://access.redhat.com/articles/yum-cheat-sheet"},{default:t(()=>[...e[1]||(e[1]=[s("Yum 速查表",-1)])]),_:1}),e[5]||(e[5]=s(" 和 ",-1)),a(i,{href:"https://fedoraproject.org/wiki/DNF?rd=Dnf"},{default:t(()=>[...e[2]||(e[2]=[s("DNF wiki",-1)])]),_:1}),e[6]||(e[6]=s("。",-1))]),e[23]||(e[23]=n("hr",null,null,-1)),n("p",null,[e[8]||(e[8]=s("via: ",-1)),a(i,{href:"https://opensource.com/article/18/8/how-install-software-linux-command-line"},{default:t(()=>[...e[7]||(e[7]=[s("https://opensource.com/article/18/8/how-install-software-linux-command-line",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=s("作者：",-1)),a(i,{href:"https://opensource.com/users/pmullins"},{default:t(()=>[...e[9]||(e[9]=[s("Patrick H.Mullins",-1)])]),_:1}),e[14]||(e[14]=s(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[10]||(e[10]=[s("lujun9972",-1)])]),_:1}),e[15]||(e[15]=s(" 译者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:t(()=>[...e[11]||(e[11]=[s("geekpi",-1)])]),_:1}),e[16]||(e[16]=s(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[12]||(e[12]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[19]||(e[19]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[17]||(e[17]=[s("LCTT",-1)])]),_:1}),e[20]||(e[20]=s(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...e[18]||(e[18]=[s("Linux中国",-1)])]),_:1}),e[21]||(e[21]=s(" 荣誉推出",-1))])])}const y=l(u,[["render",h]]);export{C as __pageData,y as default};
